using System;
using System.IO;
using System.Threading;
using System.Diagnostics;
public static class MeterProtocol {
 public static bool TryRead(byte[] p,out int first,out int[] levels){first=0;levels=null;if(p==null||p.Length<12||p[0]!=0xF0||p[1]!=0x43||(p[2]&0xF0)!=0x10||p[3]!=0x3E||p[4]!=6||p[5]!=0x21||p[6]!=0||p[7]!=0||p[8]>95||p[p.Length-1]!=0xF7||(p.Length-10)%2!=0)return false;int count=(p.Length-10)/2;if(p[8]+count>96)return false;for(int i=9;i<p.Length-1;i++)if(p[i]>127)return false;first=p[8];levels=new int[count];for(int i=0;i<count;i++)levels[i]=(p[9+i*2]<<7)|p[10+i*2];return true;}
 public static bool TryPoint(byte[] p,out bool output,out int point){output=false;point=0;if(p==null||p.Length!=14||p[0]!=0xF0||p[1]!=0x43||(p[2]&0xF0)!=0x10||p[3]!=0x3E||p[4]!=6||p[5]!=3||p[6]!=0x0C||p[7]>1||p[8]!=0||p[9]!=0||p[10]!=0||p[11]!=0||p[12]>2||p[13]!=0xF7)return false;output=p[7]==1;point=p[12];return true;}
 public static string PointLabel(int? p){return !p.HasValue?"Unknown":p.Value==0?"Pre EQ":p.Value==1?"Pre fader":"Post fader";}
 static int[] rawPoints,dbPoints;
 public static double Decibels(int raw){if(raw==0)return double.NegativeInfinity;if(rawPoints==null){string[] lines=File.ReadAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"meter-db.csv"));rawPoints=new int[lines.Length];dbPoints=new int[lines.Length];for(int i=0;i<lines.Length;i++){string[] cells=lines[i].Split(',');rawPoints[i]=int.Parse(cells[0]);dbPoints[i]=int.Parse(cells[1]);}}if(raw<=rawPoints[0])return -96;if(raw>=4095)return 0;int j=Array.BinarySearch(rawPoints,raw);if(j>=0)return dbPoints[j];j=~j;return dbPoints[j-1]+(raw-rawPoints[j-1])*(dbPoints[j]-dbPoints[j-1])/(double)(rawPoints[j]-rawPoints[j-1]);}
 public static string LevelLabel(int raw){return raw>=8191?"CLIP":raw==0?"−∞ dBFS":Decibels(raw).ToString("F1")+" dBFS";}
 public static void Test(){int first;int[] levels;byte[] packet={0xF0,0x43,0x10,0x3E,6,0x21,0,0,94,31,127,0,0,0xF7};if(!TryRead(packet,out first,out levels)||first!=94||levels.Length!=2||levels[0]!=4095||levels[1]!=0)throw new Exception("Meter decoding failed");packet[8]=95;if(TryRead(packet,out first,out levels))throw new Exception("Meter channel overflow accepted");bool output;int point;byte[] pos={0xF0,0x43,0x10,0x3E,6,3,0x0C,1,0,0,0,0,2,0xF7};if(!TryPoint(pos,out output,out point)||!output||point!=2)throw new Exception("Meter position failed");pos[12]=3;if(TryPoint(pos,out output,out point))throw new Exception("Invalid meter position accepted");if(Decibels(4095)!=0||Decibels(3840)!=-6||!double.IsNegativeInfinity(Decibels(0)))throw new Exception("Meter conversion failed");}
 public static void Probe(){string[] config=File.ReadAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"connection.ini"));uint input=0,output=0;foreach(var p in MidiInput.Devices())if(p.Value==config[0])input=p.Key;foreach(var p in FaderReader.Devices())if(p.Value==config[1])output=p.Key;using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"meter-probe.txt")))using(var source=new MidiInput(input))using(var sink=new FaderReader(output)){int device=int.Parse(config[2]);sink.ReadMeterPoint(false,device);sink.ReadMeterPoint(true,device);sink.SubscribeMeters(device);var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<3000){source.Pump();byte[] packet;while(source.Packets.TryDequeue(out packet))log.WriteLine(clock.ElapsedMilliseconds+" ms; "+packet.Length+" bytes; "+BitConverter.ToString(packet));Thread.Sleep(1);}}}
}
